package com.clinic.appointment.client;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.util.*;
@Component public class AiClient{private final RestClient client;private final String key;public AiClient(RestClient.Builder b,@Value("${clients.ai-service-url}")String url,@Value("${app.internal-api-key}")String key){client=b.baseUrl(url).build();this.key=key;}
 public PreSummary pre(String symptoms){try{return client.post().uri("/internal/ai/pre-visit").header("X-Internal-Key",key).contentType(MediaType.APPLICATION_JSON).body(Map.of("symptoms",symptoms)).retrieve().body(PreSummary.class);}catch(Exception e){return localPre(symptoms);}}
 public PostSummary post(String notes,String prescription){try{return client.post().uri("/internal/ai/post-visit").header("X-Internal-Key",key).contentType(MediaType.APPLICATION_JSON).body(Map.of("clinicalNotes",notes,"prescription",prescription)).retrieve().body(PostSummary.class);}catch(Exception e){return new PostSummary(notes,List.of(prescription),List.of("Follow the clinician's written instructions.","Contact the clinic if symptoms worsen."),"APPOINTMENT_LOCAL_RULES","AI service unavailable; clinician review is required.");}}
 private PreSummary localPre(String s){String l=s.toLowerCase();String urgency=l.matches(".*(chest pain|difficulty breathing|severe bleeding|unconscious).*" )?"HIGH":l.matches(".*(high fever|severe pain|persistent).*" )?"MEDIUM":"LOW";return new PreSummary(urgency,s,List.of("When did this begin?","What makes it better or worse?","What medicines or allergies should be considered?"),"APPOINTMENT_LOCAL_RULES","AI service unavailable; this is not a diagnosis.");}
 public record PreSummary(String urgencyLevel,String chiefComplaint,List<String> suggestedQuestions,String generatedBy,String safetyNotice){}public record PostSummary(String visitSummary,List<String> medicationSchedule,List<String> followUpSteps,String generatedBy,String safetyNotice){}
}
